BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('ffffffff-0000-4000-8000-000000000001','contracts-owner@test.local',now()),('ffffffff-0000-4000-8000-000000000002','contracts-buyer@test.local',now());
SELECT set_config('request.jwt.claims','{"sub":"ffffffff-0000-4000-8000-000000000001"}',true);
CREATE TEMP TABLE f AS SELECT public.create_property('Contract apartment','Description','Cotroceni','Exact address invisible','apartment',50,2,1,2019,10000000,50000,'{}') j;
CREATE TEMP TABLE l AS SELECT id FROM app.listings WHERE property_id=(SELECT (j->>'id')::uuid FROM f) AND transaction_type='sale';
SELECT set_config('test.contract_listing_id',(SELECT id::text FROM l),true);
SELECT is((SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(public.get_listing(current_setting('test.contract_listing_id')::uuid)) k),(SELECT array_agg(k ORDER BY k) FROM unnest(ARRAY['id','property_id','owner_id','title','description','neighborhood','judet','property_type','transaction_type','price_minor','currency','area_sqm','rooms','floor','built_year','image_urls','tenancy_status','status','lat','lng','promo_expires_at','auction_id','auction_mode','auction_access','ends_at','starts_at','current_bid_minor','bid_count','min_increment_minor','starting_price_minor','tour_url','server_now','initial_ends_at','max_ends_at','soft_close_seconds']) k),'listing has exact owner type keys');
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claims','{"role":"anon"}',true);
SELECT is((SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(public.get_listing(current_setting('test.contract_listing_id')::uuid)) k),(SELECT array_agg(k ORDER BY k) FROM unnest(ARRAY['id','property_id','title','description','neighborhood','judet','property_type','transaction_type','price_minor','currency','area_sqm','rooms','floor','built_year','image_urls','tenancy_status','status','lat','lng','promo_expires_at','auction_id','auction_mode','auction_access','ends_at','starts_at','current_bid_minor','bid_count','min_increment_minor','starting_price_minor','tour_url','server_now','initial_ends_at','max_ends_at','soft_close_seconds']) k),'anon get_listing has exact public type keys without owner_id');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"ffffffff-0000-4000-8000-000000000001"}',true);
SELECT is(public.get_listing('00000000-0000-4000-8000-000000000000'),NULL::jsonb,'unknown listing returns null');
SELECT ok((public.get_workspace()->'properties')::text LIKE '%Exact address invisible%','owner can see own address');
CREATE TEMP TABLE a AS SELECT public.start_auction((SELECT id FROM l),'sealed','invite',now()-interval '1 second',now()+interval '1 hour',1000,100) j;
SELECT set_config('request.jwt.claims','{"sub":"ffffffff-0000-4000-8000-000000000002","role":"staff","aal":"aal2"}',true);
SELECT is(public.get_listing((SELECT id FROM l))->'ends_at','null'::jsonb,'uninvited reader cannot see private auction detail');
SELECT is(public.get_listing((SELECT id FROM l))->>'auction_access','invite','private auction still advertised as invite');
SELECT throws_ok('SELECT app.require_staff()','P0001','Staff MFA required','caller-chosen role claim does not grant staff');
SELECT lives_ok(format('SELECT public.request_viewing(%L,now()+interval ''1 day'',''Visit'')',(SELECT id FROM l)),'buyer requests viewing');
SELECT throws_ok(format('SELECT public.update_viewing(%L,''confirmed'')',(SELECT id FROM app.viewings WHERE buyer_id=auth.uid())),'P0001','Invalid viewing transition','buyer cannot confirm viewing');
SELECT set_config('request.jwt.claims','{"sub":"ffffffff-0000-4000-8000-000000000001"}',true);
SELECT lives_ok(format('SELECT public.update_viewing(%L,''confirmed'')',(SELECT id FROM app.viewings WHERE listing_id=(SELECT id FROM l))),'owner confirms viewing');
UPDATE app.auctions SET ends_at=clock_timestamp()-interval '1 second' WHERE id=(SELECT (j->>'id')::uuid FROM a);
SELECT public.close_expired_auctions();
SELECT is((SELECT status FROM app.auctions WHERE id=(SELECT (j->>'id')::uuid FROM a)),'closed','independent worker closes expired auction');
SELECT is((SELECT count(*)::integer FROM app.audit_events WHERE entity_id=(SELECT (j->>'id')::uuid FROM a) AND event='auction.closed'),1,'worker appends auction closure audit once');
SELECT public.close_expired_auctions();
SELECT is((SELECT count(*)::integer FROM app.audit_events WHERE entity_id=(SELECT (j->>'id')::uuid FROM a) AND event='auction.closed'),1,'closure worker idempotent');
SET LOCAL ROLE anon;
SELECT lives_ok('SELECT public.get_catalogue()','anonymous catalogue accessible');
SELECT throws_ok('SELECT public.get_workspace()','42501',NULL,'anonymous workspace inaccessible');
SELECT throws_ok('SELECT * FROM app.properties','42501',NULL,'anonymous private property table inaccessible');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
